/**
 * @summary Check the token of each account against GitHub, as hh auth status --json; an account in error is in the array with its state
 */
export const listAccounts = async ( options?: Parameters<typeof fetcher>[1]): Promise<AuthStatus[] | null> => {

  return fetcher<AuthStatus[] | null>(getListAccountsUrl(),
  {
    ...options,
    method: 'GET'


  }
);}



export const getAddAccountUrl = () => {




  return `/api/accounts`
}

/**
 * @summary Add an account to config.yaml, as hh auth add
 */
export const addAccount = async (accountAddInputBody: AccountAddInputBody, options?: Parameters<typeof fetcher>[1]): Promise<AuthAddResult> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return fetcher<AuthAddResult>(getAddAccountUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(accountAddInputBody)
  }
);}



